import itertools

edges = [(0, 1), (0, 2), (0, 3), (0, 4),
         (1, 2), (1, 3), (1, 4),
         (2, 3), (2, 4),
         (3, 4)]

def is_valid(c):
    # Check all triangles
    triangles = list(itertools.combinations(range(5), 3))
    for t in triangles:
        e1 = edges.index((t[0], t[1]))
        e2 = edges.index((t[0], t[2]))
        e3 = edges.index((t[1], t[2]))
        if c[e1] == c[e2] == c[e3]:
            return False
    return True

for c in itertools.product([0, 1], repeat=10):
    if c[3] == 1 and c[9] == 0:
        if is_valid(c):
            print(list(c))
            break
